___CSS_LOADER_EXPORT___.push([module.id, `.native-multi-select {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  margin-bottom: 20px;
  max-width: 400px;
}

.select-label {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
}

.multi-select-field {
  width: 100%;
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: white;
  font-size: 14px;
  box-sizing: border-box;
}

.multi-select-field option {
  padding: 8px;
}

.multi-select-field option:checked {
  background-color: #e8f0fe;
  color: #1a73e8;
}

.select-info {
  margin-top: 5px;
  font-size: 12px;
  color: #666;
}

.selected-values {
  margin-top: 15px;
  padding: 10px;
  background-color: #f5f5f5;
  border-radius: 4px;
  font-size: 14px;
}

.selected-values p {
  margin: 0;
}

/* For Firefox - improve styling */
@-moz-document url-prefix() {
  .multi-select-field option {
    padding: 10px;
  }
}
/* Improve selection styling in various browsers */
.multi-select-field option:hover {
  background-color: #f5f5f5;
}

.multi-select-field:focus {
  outline: none;
  border-color: #4a90e2;
  box-shadow: 0 0 0 2px rgba(74, 144, 226, 0.2);
}

/* App styling */
.app {
  padding: 20px;
  max-width: 600px;
  margin: 0 auto;
}

.selection-result {
  margin-top: 30px;
}

.selection-result h3 {
  margin-bottom: 10px;
}

.selection-result ul {
  padding-left: 20px;
}

.selection-result li {
  margin-bottom: 5px;
